try { const saved = JSON.parse(localStorage.getItem('cleverwaste-demo-v1')||'{}'); if(saved.favorites) state.favorites=new Set(saved.favorites); if(saved.orders) state.orders=saved.orders; if(saved.profileName) state.profileName=saved.profileName; if(saved.producerOffers) state.producerOffers=saved.producerOffers; if(saved.stock) state.stock={...state.stock,...saved.stock}; if(saved.purchases) state.purchases=saved.purchases; if(saved.producerOverrides) state.producerOverrides=saved.producerOverrides; if(saved.savedTips) state.savedTips=saved.savedTips; } catch(e){}
const content = document.getElementById('app-content'), header = document.getElementById('app-header'), nav = document.getElementById('bottom-nav');
const img = id => A + id + (['050ded426449e5ac222d941a37ebca972ba6c516','22b6fa51a7decce40dfda74402cfef5e1db68c32','4b8a2316c90af5d6fb1534c900d7368a98673fe6','396f08731d0aa8aa0275ab29da07550ab27f3241','b9b6d0a82a6331c245ce9607905f7e149eeb9580','5dde4cec47ff6eae4e09d442ea7734360eb18f9d','7ee64f43228e129e3aa9bcd792012f93f48b4d68','85b95e3dc942202c6b98a3597d037635f82aaea8','050ded426449e5ac222d941a37ebca972ba6c516','6568d3bc2fc18c90f3458d61e3f3a37323a96cb9','672122d98f4cd46e44af07fa3d8d99893110dfeb','48bb3b112c34fd4198a792d5f7417607d935ca9b','cec89989efcf85e3a7227b82a5925d52fbcbd32d','acd1bc4c7f77084658995e608db89cc8d274fe3b','6265bdac695a8ff9c11ab178ecbd23badea05cd7','b2c076fd096af73d5b2d6cf40e3571a7bb39563d','7b9a287bc13b99cc4261437e4acb199529653516'].includes(id)?'.png':(['2ba9ebb0fdc67ca5658ded3389f0390cd66cb121','1882b80a3197e26998f8df76c0fc3705a51f8462','1dee40e59b7fa9f4d2c9e522602baca4a309db2f','0a6f3d9317f1c13134934bbf22edc633737818d5','22e6522c11455df8562002e6b8e9542118c4266b','e4da43442593f6c9b28e9ac624d9e2fea42ccd7b','ac3a7ac3bb34a0ad3f27fd5139943e609c1ca0fe','6378f3315dc34d0484f6ba371ad35006e492428f','2e2696d00803343e5561d6978f0cf8d51ca9aeb7','2ccee3f0036a8422ea51947e009cd8336ccb787d','7a5af0b0ecbc6852d7ebe0b3e44773ad0540e23e','823be8d6fad76eb17f1acc1396b3ad3115e023b2','2e7288c66242e075dddde0fbe1f3cf47490173bf','dec2905d8da166314c6b4460c20de92916a0f163'].includes(id)?'.jpg':'.png'));
