const safe = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('cleverwaste-demo-v1',JSON.stringify({favorites:[...state.favorites],orders:state.orders,profileName:state.profileName,producerOffers:state.producerOffers,stock:state.stock,purchases:state.purchases,producerOverrides:state.producerOverrides,savedTips:state.savedTips}));}catch(e){}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2400)}
function setPage(page,extra={}){state.page=page;Object.assign(state,extra);render();content.scrollTop=0}
function topHeader({back=false,title='',search=false,location=false}={}){
  if(back) return `<div class="header-row"><button class="icon-button" data-action="back" aria-label="Indietro">‹</button><div style="font-size:13px;font-weight:800">${safe(title)}</div><button class="icon-button" data-action="notifications" aria-label="Notifiche">♧</button></div>`;
  return `<div class="header-row"><div><div class="logo">CLEVER WASTE <b>•</b></div><div class="tagline">Think Before You Trash It</div></div><button class="icon-button" data-action="notifications" aria-label="Notifiche">♧</button></div>${location?`<div class="greeting">Ciao ${safe(state.profileName)} 👋</div><div class="location"><b>●</b> Varese e dintorni <span>⌄</span></div>`:''}${search?`<div class="searchbar"><span>⌕</span><input id="global-search" placeholder="Cerca prodotti, negozi o offerte" value="${safe(state.query)}"/><button data-action="filter">☷</button></div>`:''}`;
}
function tabs(){return state.role==='consumer'?[['Home','⌂'],['Cerca','⌕'],['Offerte','◇'],['Ordini','♧'],['Profilo','♙']]:[['Panoramica','⌂'],['Offerte','◇'],['Prenotazioni','▣'],['Scorte','▤'],['Profilo','♙']];}
function renderNav(){nav.innerHTML=tabs().map(([label,icon])=>`<button class="nav-item ${state.tab===label?'active':''}" data-tab="${label}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')}
function productCard(p){return `<article class="product-card" data-product="${p.id}" role="button" tabindex="0" aria-label="Apri offerta ${safe(p.name)}"><button class="heart-mini" data-fav="${p.id}" aria-label="${state.favorites.has(p.id)?'Rimuovi dai':'Aggiungi ai'} preferiti" aria-pressed="${state.favorites.has(p.id)}">${state.favorites.has(p.id)?'♥':'♡'}</button><img loading="lazy" decoding="async" src="${img(p.image)}" alt="${safe(p.name)}"/><div class="p-content"><h3>${safe(p.name)}</h3><div class="merchant">${safe(p.merchant)}</div><div class="price-line"><span class="price">${money(p.price)}</span><span class="old-price">${money(p.old)}</span></div><div class="discount">-${p.discount}% · ${p.distance}</div></div></article>`}
function categoryCards(){return `<div class="category-grid">${categories.slice(0,6).map(c=>`<button class="category-card" data-category="${safe(c.filter)}"><img loading="lazy" decoding="async" src="${img(c.image)}" alt=""/><div class="cat-label">${safe(c.name)}</div><div class="cat-sub">${safe(c.sub)}</div></button>`).join('')}</div>`}
function productSection(list=products,limit=4){return `<div class="product-list" role="list">${list.slice(0,limit).map(productCard).join('')}</div>`}
function renderHome(){header.innerHTML=topHeader({location:true,search:true});const picks=[...products].sort((a,b)=>a.distance.localeCompare(b.distance));content.innerHTML=`<div class="hero-banner"><div class="hero-copy"><span class="eyebrow">MENO SPRECHI, PIÙ GUSTO</span><h2>Il cibo buono merita un domani.</h2><p>Salvalo. Risparmia. Sorridi.</p><button data-page="impact">Scopri come →</button></div><img src="${img(IMG.vegetables)}" alt="Ortaggi di stagione"/></div><div class="section"><div class="section-heading"><div><h2>Esplora le categorie</h2><div class="subtext">10 categorie indipendenti · Scopri →</div></div><button data-tab="Cerca">Vedi tutte</button></div>${categoryCards()}</div><div class="section"><div class="section-heading"><div><h2>Offerte vicino a te</h2><div class="subtext">Occasioni disponibili oggi a Varese</div></div><button data-tab="Offerte">Vedi tutte</button></div>${productSection(picks,4)}</div><div class="section"><div class="section-heading"><div><h2>Le migliori occasioni</h2><div class="subtext">Prodotti selezionati per te</div></div><button data-tab="Offerte">Esplora</button></div>${productSection(products.slice(4),4)}</div><div class="card"><div class="row between"><div><b style="font-size:12px">Da ritirare oggi?</b><div class="subtext">Prenota ora e ritira direttamente in negozio.</div></div><span style="font-size:24px">♧</span></div><button class="btn secondary full" style="margin-top:10px" data-tab="Ordini">Vai ai tuoi ordini</button></div>`;}
function renderSearch(){header.innerHTML=topHeader({back:false});content.innerHTML=`<div class="section-heading"><div><h1 class="h1">Cerca</h1><p class="page-intro">Trova prodotti, negozi e occasioni vicino a te.</p></div></div><div class="searchbar" style="margin:0 0 10px"><span>⌕</span><input id="search-page" placeholder="Cerca prodotti, negozi o offerte" value="${safe(state.query)}"/><button data-action="filter">☷</button></div><div class="section"><div class="section-heading"><h2>Ricerche recenti</h2><button data-action="clear-search">Cancella</button></div><div class="chip-row">${['pane','verdura','pizza','focaccia'].map(q=>`<button class="chip" data-query="${q}">${q}</button>`).join('')}</div></div><div class="section"><div class="section-heading"><h2>Categorie alimentari</h2></div>${categoryCards()}</div><div class="section"><div class="section-heading"><h2>Risultati della ricerca</h2><span class="subtext" id="result-count"></span></div><div id="search-results" class="results-grid-host">${productSection(filteredProducts(),11)}</div></div>`;updateSearchResults();}
function filteredProducts(){let q=(state.query||'').toLowerCase();return products.filter(p=>(state.category==='Tutte'||p.category===state.category||p.group===state.category)&&(!q||`${p.name} ${p.merchant} ${p.category} ${p.group}`.toLowerCase().includes(q)));}
function updateSearchResults(){let el=document.getElementById('search-results');if(el){const res=filteredProducts();el.innerHTML=res.length?productSection(res,11):`<div class="empty"><div class="emoji">⌕</div>Nessun risultato. Prova un'altra ricerca o categoria.</div>`;const c=document.getElementById('result-count');if(c)c.textContent=`${res.length} risultati`;}}
function renderOffers(){header.innerHTML=topHeader({back:false});const filters=['Tutte','-50%','Pane e dolci','Piatti pronti','Frutta e verdura'];content.innerHTML=`<h1 class="h1">Offerte</h1><p class="page-intro">Le occasioni disponibili nei negozi indipendenti vicino a te.</p><div class="chip-row">${filters.map(f=>`<button class="chip ${state.activeFilter===f?'active':''}" data-offer-filter="${safe(f)}">${f}</button>`).join('')}</div><div class="section-heading"><div><h2>Catalogo delle offerte</h2><div class="subtext">Ritiro diretto dal commerciante</div></div><button data-action="sort">⇅ Ordina</button></div><div id="offer-results" class="results-grid-host">${productSection(offerFiltered(),11)}</div>`;}
function offerFiltered(){let list=products.filter(p=>state.activeFilter==='Tutte'||(state.activeFilter==='-50%'&&p.discount>=50)||p.group===state.activeFilter);if(state.sort==='Prezzo crescente')list.sort((a,b)=>a.price-b.price);if(state.sort==='Prezzo decrescente')list.sort((a,b)=>b.price-a.price);return list;}
function renderOrders(){header.innerHTML=topHeader({back:false});const pending=state.orders.filter(o=>o.status!=='Ritirato');const completed=state.orders.filter(o=>o.status==='Ritirato');content.innerHTML=`<h1 class="h1">Ordini</h1><p class="page-intro">Le tue prenotazioni e gli ultimi acquisti.</p><div class="card" style="background:#173d2e;color:white"><div class="row between"><div><div class="eyebrow">PRENOTAZIONI DA RITIRARE</div><div style="font-size:24px;font-weight:800;margin-top:4px">${pending.length}</div></div><div style="font-size:26px">▣</div></div><div class="small" style="color:#d8e5dc;margin-top:7px">Presenta la prenotazione direttamente al negozio.</div></div><div class="section-heading"><h2>Ordini attivi</h2><span class="pill">${pending.length} attivi</span></div>${pending.length?pending.map(orderCard).join(''):`<div class="empty"><div class="emoji">♧</div>Non hai prenotazioni attive.<br/>Scopri le offerte e prenota la tua prima occasione.</div>`}<div class="section-heading"><h2>Ordini completati</h2><span class="subtext">${completed.length}</span></div>${completed.length?completed.map(orderCard).join(''):`<div class="card small muted">I tuoi acquisti completati compariranno qui.</div>`}`;}
function orderCard(o){return `<div class="card"><div class="row"><img src="${img(o.image)}" style="width:62px;height:62px;border-radius:10px;object-fit:cover"/><div style="min-width:0;flex:1"><b style="font-size:11px">${safe(o.name)}</b><div class="subtext">${safe(o.merchant)} · ${o.code}</div><div class="subtext">${safe(o.pickup)}</div></div><b style="font-size:13px;color:var(--green)">${money(o.price*o.qty)}</b></div><div class="row between" style="margin-top:10px"><span class="pill ${o.status==='Ritirato'?'gold':''}">${o.status}</span><button class="text-link" data-order="${o.code}">Dettagli →</button></div></div>`}
function renderProfile(){header.innerHTML=topHeader({back:false});const total=state.orders.reduce((s,o)=>s+o.price*o.qty,0)+37.5;content.innerHTML=`<h1 class="h1">Profilo</h1><div class="profile-top"><div class="avatar">${safe((state.profileName||'P').slice(0,1).toUpperCase())}</div><div style="flex:1"><b style="font-size:13px">${safe(state.profileName)}</b><div class="subtext">Membro Clever Waste · Varese</div></div><span class="pill gold">Risparmiatore</span></div><div class="section"><div class="stat-grid"><div class="stat"><div class="caption">IL MIO RISPARMIO</div><div class="num">${money(total)}</div><div class="caption">Valore dimostrativo</div></div><div class="stat"><div class="caption">CLEVER POINTS</div><div class="num">120</div><div class="caption">Punti dimostrativi</div></div></div></div><div class="card"><div class="row between"><b style="font-size:12px">Il tuo valore, ogni giorno</b><span class="pill">Livello 2</span></div><div style="height:8px;background:#e6eddf;border-radius:8px;margin:12px 0 5px;overflow:hidden"><div style="height:100%;width:68%;background:#267653;border-radius:8px"></div></div><div class="row between small muted"><span>120 punti</span><span>Obiettivo 180</span></div></div><div class="section"><button class="menu-row" data-page="savings"><span>◉ Il mio risparmio</span><span>›</span></button><button class="menu-row" data-page="points"><span>✦ Clever Points</span><span>›</span></button><button class="menu-row" data-page="rewards"><span>♛ Premi e vantaggi</span><span>›</span></button><button class="menu-row" data-page="badges"><span>♢ Livelli e badge</span><span>›</span></button><button class="menu-row" data-page="impact"><span>♧ Impatto ambientale</span><span>›</span></button><button class="menu-row" data-page="preferences"><span>⚙ Notifiche e preferenze</span><span>›</span></button><button class="menu-row" data-page="welcome"><span>⇄ Accesso e scelta del profilo</span><span>›</span></button></div><div class="card"><b style="font-size:12px">Gestione profilo</b><label class="label">Nome visualizzato</label><input id="profile-name" class="field" value="${safe(state.profileName)}"/><button class="btn secondary full" style="margin-top:9px" data-action="save-profile">Salva modifiche</button></div><div class="card"><b style="font-size:12px">Sei un produttore?</b><p class="subtext">Accedi all'area dimostrativa per gestire offerte, prenotazioni e scorte.</p><button class="btn full" data-action="switch-role">Passa all'area produttore →</button></div><div class="notice">Demo: profilo e dati sono dimostrativi. Non viene creato un account online.</div>`;}
