function renderDetailSub(){const map={savings:['Il mio risparmio','Il risparmio in numeri','Hai risparmiato 37,50 € nelle tue occasioni dimostrative.'],points:['Clever Points','Il saldo punti','120 punti dimostrativi accumulati con le attività di esempio.'],rewards:['Premi e vantaggi','Vantaggi e livelli','Scopri i vantaggi disponibili nella demo.'],badges:['Livelli e badge','I tuoi riconoscimenti','Continua a scegliere le eccedenze per avanzare di livello.'],impact:['Impatto ambientale','Il tuo impatto in numeri','Un modo concreto per dare valore al cibo.'],preferences:['Notifiche e preferenze','Frequenza e silenzio','Gestisci le notifiche che desideri ricevere.']};const [title,h,desc]=map[state.page]||map.savings;header.innerHTML=topHeader({back:true,title});content.innerHTML=`<h1 class="h1">${h}</h1><p class="page-intro">${desc}</p><div class="stat-grid"><div class="stat"><div class="caption">VALORE SALVATO</div><div class="num">37,50 €</div><div class="caption">Dati dimostrativi</div></div><div class="stat"><div class="caption">ATTIVITÀ</div><div class="num">12</div><div class="caption">Esempi nel profilo</div></div></div><div class="card"><h2 class="h2">${title}</h2><p class="page-intro">Questi dati sono esempi di presentazione, non transazioni o impatti misurati su un account reale.</p><div class="bars"><div class="bar-col"><div class="bar" style="height:35%"></div><span class="bar-label">Set</span></div><div class="bar-col"><div class="bar" style="height:55%"></div><span class="bar-label">Ott</span></div><div class="bar-col"><div class="bar alt" style="height:82%"></div><span class="bar-label">Nov</span></div><div class="bar-col"><div class="bar" style="height:68%"></div><span class="bar-label">Dic</span></div></div></div><button class="btn secondary full" data-tab="Profilo">Torna al profilo</button>`;}
