function renderProducerHome(){content.innerHTML=`<div class="producer-head"><span class="eyebrow">DASHBOARD ATTIVITÀ</span><h2>Buongiorno, Panificio del Borgo 👋</h2><p><span class="status-dot"></span>Attività dimostrativa · Varese</p></div><div class="stat-grid"><div class="stat"><div class="caption">RICAVI DA RECUPERO</div><div class="num">186,40 €</div><div class="caption">+12% vs periodo precedente</div></div><div class="stat"><div class="caption">PRENOTAZIONI</div><div class="num">42</div><div class="caption">12 in attesa di ritiro</div></div><div class="stat"><div class="caption">PRODOTTI RECUPERATI</div><div class="num">68</div><div class="caption">unità dimostrative</div></div><div class="stat"><div class="caption">SPRECO EVITATO</div><div class="num">24,6 kg</div><div class="caption">stima di esempio</div></div></div><div class="section-heading"><h2>Le tue attività</h2><button data-tab="Offerte">Gestisci →</button></div><div class="card"><div class="row between"><div><b style="font-size:11px">Offerte pubblicate</b><div class="subtext">12 attive · 3 in esaurimento</div></div><span class="pill">Attiva</span></div><div class="row between" style="margin-top:12px"><div><b style="font-size:11px">Prenotazioni</b><div class="subtext">Ritiri da preparare</div></div><button class="btn secondary" data-tab="Prenotazioni">Apri</button></div><div class="row between" style="margin-top:12px"><div><b style="font-size:11px">Acquisti e scorte</b><div class="subtext">Aggiorna disponibilità</div></div><button class="btn secondary" data-tab="Scorte">Apri</button></div></div><div class="card"><div class="row between"><div><div class="eyebrow" style="color:#ad8a27">SERVIZIO PREMIUM · DEMO</div><h2 class="h2">Clever Waste AI</h2></div><span style="font-size:26px">✦</span></div><p class="page-intro">Analisi di vendite, prenotazioni, scorte e prodotti invenduti.</p><div class="notice">Premium non attivo · prezzo in definizione. Le analisi mostrate sono simulate e non attivano pagamenti.</div><button class="btn gold full" data-page="ai">Apri analisi AI →</button></div><button class="btn secondary full" data-action="switch-role">Torna all'area cliente</button>`;}
function producerOfferRows(){
 const samples=[
  {id:'sample-focaccia',name:'Focacce del giorno',price:'4,50 €',rawPrice:4.5,qty:'18 disponibili',qtyNumber:18,status:'Attiva',image:IMG.focaccia},
  {id:'sample-vegetables',name:'Ortaggi di stagione',price:'3,90 €',rawPrice:3.9,qty:'32 disponibili',qtyNumber:32,status:'Attiva',image:IMG.vegetables},
  {id:'sample-pizza',name:'Pizza margherita',price:'4,50 €',rawPrice:4.5,qty:'12 disponibili',qtyNumber:12,status:'Attiva',image:IMG.pizza}
 ].map(o=>({...o,...(state.producerOverrides[o.id]||{})}));
 return [...samples,...state.producerOffers];
}
function renderProducerOffers(){
 const rows=producerOfferRows();
 const shown=rows.filter(o=>state.offerFilter==='Tutte'||o.status===state.offerFilter);
 content.innerHTML=`<div class="row between"><h1 class="h1">Le tue offerte</h1><button class="btn" data-action="new-offer">＋ Nuova</button></div><p class="page-intro">Gestisci le offerte condivise con i consumatori.</p><div class="chip-row">${['Tutte','Attiva','Bozza','Esaurita'].map(f=>`<button class="chip ${state.offerFilter===f?'active':''}" data-producer-filter="${f}">${f==='Attiva'?'Attive':f==='Bozza'?'Bozze':f==='Esaurita'?'Esaurite':f}</button>`).join('')}</div>${shown.length?shown.map(o=>`<div class="card"><div class="row"><img loading="lazy" src="${img(o.image||IMG.focaccia)}" alt="" class="producer-offer-thumb"/><div class="producer-offer-copy"><b>${safe(o.name)}</b><div class="subtext">${safe(o.price)} · ${safe(o.qty)}</div><span class="pill">${safe(o.status)}</span></div><button class="icon-button" data-action="edit-offer" data-id="${safe(o.id)}" aria-label="Modifica ${safe(o.name)}">✎</button></div><div class="row between" style="margin-top:10px"><span class="subtext">Dati dimostrativi</span><button class="text-link" data-action="offer-stats">Statistiche →</button></div></div>`).join(''):`<div class="empty">Nessuna offerta in questa sezione.</div>`}<button class="btn secondary full" data-action="new-offer">＋ Crea una nuova offerta</button>`;
}
function renderProducerBookings(){content.innerHTML=`<h1 class="h1">Prenotazioni</h1><p class="page-intro">Prenotazioni ricevute dai clienti · dati dimostrativi.</p><div class="stat-grid"><div class="stat"><div class="caption">DA PREPARARE</div><div class="num">12</div></div><div class="stat"><div class="caption">DA RITIRARE</div><div class="num">7</div></div></div>${[['CW1048','Focaccia del forno','Pau Soler Rodà','17:00–18:00','Da preparare'],['CW1049','Cassetta di stagione','Cliente demo','17:30–18:30','Pronta al ritiro'],['CW1050','Pane assortito','Cliente demo','18:00–19:00','Da preparare']].map((o,i)=>`<div class="card"><div class="row between"><span class="pill">${o[0]}</span><b class="small">${o[3]}</b></div><b style="display:block;font-size:12px;margin-top:9px">${o[1]}</b><div class="subtext">${o[2]}</div><div class="row between" style="margin-top:10px"><span class="subtext">${safe(state.bookingStatuses[i]||o[4])}</span><button class="btn secondary" data-action="booking-status" data-id="${i}">Aggiorna</button></div></div>`).join('')}`;}
