function renderProducerProfile(){content.innerHTML=`<h1 class="h1">Profilo attività</h1><div class="profile-top"><div class="avatar">PB</div><div><b style="font-size:12px">Panificio del Borgo</b><div class="subtext">Attività indipendente · Varese</div></div></div><div class="card"><b style="font-size:11px">Il tuo servizio AI</b><p class="page-intro">Premium non attivo · prezzo in definizione.</p><button class="btn gold full" data-page="ai">Gestisci il servizio AI</button></div><button class="menu-row" data-page="report"><span>▥ Report economico e ambientale</span><span>›</span></button><button class="menu-row" data-page="ai-advice"><span>✦ Consigli sugli acquisti</span><span>›</span></button><button class="menu-row" data-action="switch-role"><span>⇄ Cambia profilo · area cliente</span><span>›</span></button>`;}
function renderProducerSub(){const pages={ai:['Clever Waste AI','Analisi dimostrativa','Analisi di vendite, prenotazioni, scorte e prodotti invenduti.'],report:['Report economico e ambientale','Il valore recuperato','Risultati di esempio per il periodo selezionato.'], 'ai-advice':['Consigli sugli acquisti','Suggerimenti per le prossime forniture','Indicazioni simulate per ridurre eccedenze e rotture di stock.']};const [title,sub,desc]=pages[state.page]||pages.ai;header.innerHTML=topHeader({back:true,title});content.innerHTML=`<div class="producer-head"><span class="eyebrow">INSIGHT DEMO · NON DATI REALI</span><h2>${title}</h2><p>${desc}</p></div><div class="stat-grid"><div class="stat"><div class="caption">VALORE RECUPERATO</div><div class="num">186,40 €</div></div><div class="stat"><div class="caption">SPRECO EVITATO</div><div class="num">24,6 kg</div></div><div class="stat"><div class="caption">PRENOTAZIONI</div><div class="num">42</div></div><div class="stat"><div class="caption">PRODOTTI INVENDUTI</div><div class="num">18</div></div></div><div class="card"><h2 class="h2">${sub}</h2><p class="page-intro">${state.page==='ai-advice'?'Aumenta la produzione di pane nei giorni di maggiore domanda; riduci leggermente gli acquisti di prodotti freschi a rotazione più lenta.':'Le prenotazioni di focacce e pane hanno generato il maggior recupero. Le eccedenze di ortaggi si concentrano a fine giornata.'}</p><div class="bars"><div class="bar-col"><div class="bar" style="height:50%"></div><span class="bar-label">Lun</span></div><div class="bar-col"><div class="bar" style="height:68%"></div><span class="bar-label">Mar</span></div><div class="bar-col"><div class="bar alt" style="height:90%"></div><span class="bar-label">Mer</span></div><div class="bar-col"><div class="bar" style="height:62%"></div><span class="bar-label">Gio</span></div><div class="bar-col"><div class="bar" style="height:74%"></div><span class="bar-label">Ven</span></div></div></div><div class="card"><b style="font-size:11px">Raccomandazione</b><p class="page-intro">Monitora le quantità invendute prima di confermare il prossimo ordine di materie prime. Valuta offerte mirate nelle fasce orarie con più eccedenze.</p><button class="btn secondary full" data-action="ai-tip">Salva suggerimento</button></div><div class="notice">Il servizio AI è rappresentato con analisi e dati simulati. Non sono connessi registri di cassa, magazzino o sistemi esterni; non vengono attivati pagamenti.</div>`;}
function renderWelcome(){header.innerHTML='';content.innerHTML=`<div style="padding:18px 0;text-align:center"><div class="logo" style="font-size:25px">CLEVER WASTE <b>•</b></div><div class="tagline">Think Before You Trash It</div><img src="${img(IMG.vegetables)}" style="width:100%;height:185px;object-fit:cover;border-radius:17px;margin:20px 0"/><h1 class="h1">Benvenuto in Clever Waste</h1><p class="page-intro">Meno sprechi, più gusto. Scegli come vuoi utilizzare la demo.</p><button class="btn full" data-page="choose-profile">Scegli il profilo</button><button class="btn secondary full" style="margin-top:9px" data-page="login">Accedi o registrati</button><div class="notice">Registrazione e accesso sono dimostrativi. Non vengono creati account online.</div></div>`;}
function renderAuthPage(){const type=state.page;const title=type==='login'?'Accesso consumatore':type==='register'?'Registrazione consumatore':'Recupero password';header.innerHTML=topHeader({back:true,title});if(type==='login'){content.innerHTML=`<h1 class="h1">Bentornato!</h1><p class="page-intro">Accedi alla tua area personale Clever Waste.</p><label class="label">Email</label><input class="field" id="auth-email" type="email" placeholder="pau@example.com"/><label class="label">Password</label><input class="field" id="auth-password" type="password" placeholder="Inserisci la password"/><button class="btn full" style="margin-top:14px" data-action="demo-login">Accedi</button><button class="btn secondary full" style="margin-top:8px" data-action="choose-consumer">Entra in modalità demo</button><div class="row between" style="margin-top:12px"><button class="text-link" data-page="register">Registrati</button><button class="text-link" data-page="recover">Recupera password</button></div><div class="notice">Accesso dimostrativo: non vengono create sessioni online né salvate credenziali.</div>`;}else if(type==='register'){content.innerHTML=`<h1 class="h1">Crea il tuo profilo</h1><p class="page-intro">Registrazione guidata dimostrativa.</p><label class="label">Nome</label><input class="field" id="register-name" placeholder="Il tuo nome"/><label class="label">Email</label><input class="field" id="register-email" type="email" placeholder="nome@email.it"/><label class="label">Password</label><input class="field" id="register-password" type="password" placeholder="Crea una password demo"/><button class="btn full" style="margin-top:14px" data-action="demo-register">Registrati in demo</button><button class="text-link" style="margin-top:12px" data-page="login">Hai già un account? Accedi</button><div class="notice">Non vengono creati account online né salvate password reali.</div>`;}else{content.innerHTML=`<h1 class="h1">Recupera password</h1><p class="page-intro">Inserisci la tua email: visualizzerai una conferma dimostrativa.</p><label class="label">Email</label><input class="field" id="recover-email" type="email" placeholder="nome@email.it"/><button class="btn full" style="margin-top:14px" data-action="demo-recover">Invia richiesta</button><button class="text-link" style="margin-top:12px" data-page="login">Torna all'accesso</button><div class="notice">Il recupero è simulato e non invia email.</div>`;}}
function renderChooseProfile(){header.innerHTML=topHeader({back:true,title:'Scegli il profilo'});content.innerHTML=`<h1 class="h1">Come vuoi utilizzare Clever Waste?</h1><p class="page-intro">Scegli il percorso da esplorare nella demo.</p><div class="card"><div class="row"><div class="avatar">☺</div><div style="flex:1"><b style="font-size:12px">Sono un consumatore</b><div class="subtext">Scopri le offerte, prenota e risparmia.</div></div></div><button class="btn full" style="margin-top:12px" data-action="choose-consumer">Continua come consumatore</button></div><div class="card"><div class="row"><div class="avatar">♧</div><div style="flex:1"><b style="font-size:12px">Sono un produttore</b><div class="subtext">Gestisci offerte, prenotazioni, scorte e report.</div></div></div><button class="btn secondary full" style="margin-top:12px" data-action="choose-producer">Continua come produttore</button></div>`;}

function render(){if(['ai','report','ai-advice'].includes(state.page)){renderProducerSub();renderNav();return;}if(state.role==='producer'&&['Panoramica','Offerte','Prenotazioni','Scorte','Profilo'].includes(state.tab)){renderProducer();renderNav();return;}if(state.page==='welcome'){renderWelcome();nav.innerHTML='';return;}if(state.page==='choose-profile'){renderChooseProfile();renderNav();return;}if(['login','register','recover'].includes(state.page)){renderAuthPage();nav.innerHTML='';return;}if(state.page==='detail'){renderDetail();renderNav();return;}if(state.page==='notifications'){renderNotifications();renderNav();return;}if(['savings','points','rewards','badges','impact','preferences'].includes(state.page)){header.innerHTML=topHeader({back:true,title:({savings:'Il mio risparmio',points:'Clever Points',rewards:'Premi e vantaggi',badges:'Livelli e badge',impact:'Impatto ambientale',preferences:'Preferenze'})[state.page]});renderDetailSub();renderNav();return;}if(state.role==='producer'){renderProducer();renderNav();return;}switch(state.tab){case'Home':renderHome();break;case'Cerca':renderSearch();break;case'Offerte':renderOffers();break;case'Ordini':renderOrders();break;case'Profilo':renderProfile();break;default:renderHome();}renderNav();}
// Events — delegated so that every new screen remains interactive.
document.addEventListener('click',e=>{
 const tab=e.target.closest('[data-tab]'); if(tab){const t=tab.dataset.tab;state.page='tab';state.tab=t;state.category='Tutte';state.activeFilter='Tutte';render();content.scrollTop=0;return;}
 const cat=e.target.closest('[data-category]');if(cat){state.category=cat.dataset.category;state.query='';state.tab='Cerca';state.page='tab';render();content.scrollTop=0;return;}
 const prod=e.target.closest('[data-product]');if(prod&&!e.target.closest('[data-fav]')){state.returnTab=state.tab;state.selected=prod.dataset.product;state.qty=1;setPage('detail');return;}
 const fav=e.target.closest('[data-fav]');if(fav){const id=fav.dataset.fav;state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);persist();render();toast(state.favorites.has(id)?'Aggiunto ai preferiti':'Rimosso dai preferiti');return;}
 const pf=e.target.closest('[data-producer-filter]');if(pf){state.offerFilter=pf.dataset.producerFilter;renderProducerOffers();return;}
 const of=e.target.closest('[data-offer-filter]');if(of){state.activeFilter=of.dataset.offerFilter;renderOffers();return;}
 const query=e.target.closest('[data-query]');if(query){state.query=query.dataset.query;state.tab='Cerca';render();return;}
 const order=e.target.closest('[data-order]');if(order){const o=state.orders.find(x=>x.code===order.dataset.order);if(o)modalOrder(o);return;}
 const stock=e.target.closest('[data-stock]');if(stock){state.stock[stock.dataset.stock]=(state.stock[stock.dataset.stock]||0)+5;persist();renderProducerStock();toast('Scorta aggiornata');return;}
 const page=e.target.closest('[data-page]');if(page){setPage(page.dataset.page);return;}
 const action=e.target.closest('[data-action]');if(!action)return;
 switch(action.dataset.action){
  case'back': if(state.page==='detail'||state.page==='notifications'||['savings','points','rewards','badges','impact','preferences','ai','report','ai-advice'].includes(state.page)){state.page='tab';state.tab=state.role==='producer'?'Panoramica':(state.returnTab||'Offerte');render();}else{state.page='tab';render();}break;
  case'notifications':setPage('notifications');break;
  case'filter':modalFilters();break;
  case'clear-search':state.query='';renderSearch();break;
  case'sort':state.sort=state.sort==='Consigliate'?'Prezzo crescente':state.sort==='Prezzo crescente'?'Prezzo decrescente':'Consigliate';toast(`Ordine: ${state.sort}`);renderOffers();break;
  case'reserve':{const p=product(state.selected);if(p.qty<=0){toast('Questa offerta è esaurita');break;}state.qty=Math.min(Math.max(1,state.qty),p.qty);modalReserve();break;}
  case'save-profile':{const v=document.getElementById('profile-name')?.value.trim();if(v){state.profileName=v;persist();renderProfile();toast('Profilo demo aggiornato');}else toast('Inserisci un nome');break;}
  case'demo-login':{const email=document.getElementById('auth-email')?.value.trim(),pass=document.getElementById('auth-password')?.value;if(!email||!pass){toast('Inserisci email e password demo');break;}state.role='consumer';state.page='tab';state.tab='Home';render();toast('Accesso demo effettuato');break;}
  case'demo-register':{const name=document.getElementById('register-name')?.value.trim(),email=document.getElementById('register-email')?.value.trim(),pass=document.getElementById('register-password')?.value;if(!name||!email||!pass){toast('Completa tutti i campi');break;}state.profileName=name;persist();state.role='consumer';state.page='tab';state.tab='Home';render();toast('Profilo creato in modalità demo');break;}
  case'demo-recover':{const email=document.getElementById('recover-email')?.value.trim();if(!email){toast('Inserisci un indirizzo email');break;}toast('Richiesta di recupero simulata');break;}
  case'switch-role':state.role=state.role==='consumer'?'producer':'consumer';state.tab=state.role==='producer'?'Panoramica':'Profilo';state.page='tab';render();toast(state.role==='producer'?'Area produttore demo':'Area cliente');break;
  case'choose-consumer':state.role='consumer';state.tab='Home';state.page='tab';render();break;
  case'choose-producer':state.role='producer';state.tab='Panoramica';state.page='tab';render();break;
  case'new-offer':modalNewOffer();break;
  case'edit-offer':modalEditOffer(action.dataset.id);break;
  case'offer-stats':setPage('report');break;
  case'booking-status':{const i=Number(action.dataset.id),cycle=['Da preparare','Pronta al ritiro','Ritirata'];const current=state.bookingStatuses[i]||'Da preparare';state.bookingStatuses[i]=cycle[(cycle.indexOf(current)+1)%cycle.length];renderProducerBookings();toast('Stato prenotazione aggiornato');break;}
  case'register-purchase':modalPurchase();break;
  case'ai-tip':state.savedTips.push('Suggerimento acquisti salvato');persist();toast('Suggerimento salvato nella demo');break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='search-page'||e.target.id==='global-search'){state.query=e.target.value;if(e.target.id==='global-search'){state.tab='Cerca';state.page='tab';renderSearch();renderNav();document.getElementById('search-page')?.focus();}else updateSearchResults();}});
document.addEventListener('click',e=>{const qty=e.target.closest('[data-qty]');if(qty){const p=product(state.selected);if(p.qty<=0){toast('Questa offerta è esaurita');return;}state.qty=Math.max(1,Math.min(p.qty,state.qty+Number(qty.dataset.qty)));renderDetail();return;}});
function mountModal(inner){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" data-close-modal><div class="modal" role="dialog" aria-modal="true">${inner}</div></div>`;}
function closeModal(){document.getElementById('modal-root').innerHTML='';}
document.getElementById('modal-root').addEventListener('click',e=>{if(e.target.hasAttribute('data-close-modal')||e.target.closest('[data-close]'))closeModal();});
function modalReserve(){const p=product(state.selected);mountModal(`<div class="row between"><div><h2>Conferma prenotazione</h2><p>${safe(p.name)} · ${safe(p.merchant)}</p></div><button class="close" data-close>×</button></div><div class="card"><div class="row between"><span class="small">Quantità</span><b>${state.qty}</b></div><div class="row between"><span class="small">Prezzo unitario</span><b>${money(p.price)}</b></div><div class="row between"><span class="small">Totale</span><b class="price">${money(p.price*state.qty)}</b></div></div><label class="label">Fascia di ritiro</label><select class="field" id="pickup-slot"><option>${safe(p.pickup)}</option><option>Domani, 10:00–12:00</option></select><div class="notice">Prenotazione simulata: nessun pagamento verrà effettuato. I dati resteranno in questa demo.</div><div class="modal-actions"><button class="btn secondary" data-close>Annulla</button><button class="btn" data-confirm-reserve>Conferma prenotazione</button></div>`);}
document.getElementById('modal-root').addEventListener('click',e=>{const picked=e.target.closest('[data-mark-picked]');if(picked){const order=state.orders.find(o=>o.code===picked.dataset.markPicked);if(order){order.status='Ritirato';persist();closeModal();renderOrders();toast('Ordine segnato come ritirato');}return;}});
document.getElementById('modal-root').addEventListener('click',e=>{const btn=e.target.closest('[data-confirm-reserve]');if(btn){const p=product(state.selected);if(p.qty<state.qty||p.qty<=0){closeModal();toast('Quantità non più disponibile: aggiorna l’offerta');return;}const slot=document.getElementById('pickup-slot').value;const o={code:'CW'+(1048+state.orders.length),name:p.name,merchant:p.merchant,price:p.price,qty:state.qty,pickup:slot,status:'Confermata · da ritirare',image:p.image};p.qty=Math.max(0,p.qty-state.qty);state.orders.unshift(o);persist();closeModal();state.tab='Ordini';state.page='tab';state.role='consumer';render();toast('Prenotazione confermata nella demo');}});
function modalFilters(){mountModal(`<div class="row between"><h2>Filtri di ricerca</h2><button class="close" data-close>×</button></div><label class="label">Categoria</label><select class="field" id="filter-category"><option>Tutte</option>${categories.map(c=>`<option>${safe(c.filter)}</option>`).join('')}</select><label class="label">Ordina le offerte</label><select class="field" id="filter-sort"><option>Consigliate</option><option>Prezzo crescente</option><option>Prezzo decrescente</option></select><div class="modal-actions"><button class="btn secondary" data-close>Annulla</button><button class="btn" data-apply-filters>Applica filtri</button></div>`);}
document.getElementById('modal-root').addEventListener('click',e=>{if(e.target.closest('[data-apply-filters]')){state.category=document.getElementById('filter-category').value;state.sort=document.getElementById('filter-sort').value;closeModal();state.tab='Cerca';renderSearch();toast('Filtri applicati');}});
function modalOrder(o){mountModal(`<div class="row between"><h2>${safe(o.code)}</h2><button class="close" data-close>×</button></div><p>${safe(o.name)} · ${safe(o.merchant)}</p><div class="card"><div class="row between"><span class="small">Quantità</span><b>${o.qty}</b></div><div class="row between"><span class="small">Totale</span><b>${money(o.price*o.qty)}</b></div><div class="row between"><span class="small">Ritiro</span><b class="small">${safe(o.pickup)}</b></div><div style="margin-top:9px"><span class="pill">${safe(o.status)}</span></div></div><div class="notice">Codice e ordine esclusivamente dimostrativi.</div>${o.status!=='Ritirato'?`<button class="btn full" data-mark-picked="${safe(o.code)}">Segna come ritirato</button>`:''}<button class="btn secondary full" style="margin-top:8px" data-close>Chiudi</button>`);}
function modalNewOffer(){mountModal(`<div class="row between"><h2>Nuova offerta</h2><button class="close" data-close>×</button></div><p>Inserisci i dati di una nuova eccedenza da condividere.</p><label class="label">Nome prodotto</label><input class="field" id="new-name" placeholder="Es. Pane del giorno"/><div class="form-grid"><div><label class="label">Prezzo (€)</label><input class="field" id="new-price" type="number" min="0" step="0.10" placeholder="4,50"/></div><div><label class="label">Quantità</label><input class="field" id="new-qty" type="number" min="1" placeholder="6"/></div></div><label class="label">Categoria</label><select class="field" id="new-category">${categories.map(c=>`<option>${safe(c.filter)}</option>`).join('')}</select><div class="notice">La pubblicazione è simulata e non rende l'offerta visibile a utenti reali.</div><div class="modal-actions"><button class="btn secondary" data-close>Annulla</button><button class="btn" data-create-offer>Salva bozza</button></div>`);}
document.getElementById('modal-root').addEventListener('click',e=>{if(e.target.closest('[data-create-offer]')){const name=document.getElementById('new-name').value.trim(),price=Number(document.getElementById('new-price').value),qty=Number(document.getElementById('new-qty').value);if(!name||!(price>0)||!(qty>0)){toast('Completa nome, prezzo e quantità');return;}state.producerOffers.unshift({id:'offer-'+Date.now(),name,price:money(price),rawPrice:price,qty:`${qty} disponibili`,qtyNumber:qty,status:'Bozza',image:IMG.focaccia});persist();closeModal();renderProducerOffers();toast(`Bozza “${name}” salvata nella demo`);}});

function modalEditOffer(id){
 const offer=producerOfferRows().find(o=>o.id===id);
 if(!offer){toast('Offerta non trovata');return;}
 const raw=Number(offer.rawPrice)||Number(String(offer.price).replace(',','.').replace(/[^0-9.]/g,''))||0;
 const q=Number(offer.qtyNumber)||Number(String(offer.qty).match(/\d+/)?.[0])||1;
 mountModal(`<div class="row between"><h2>Modifica offerta</h2><button class="close" data-close>×</button></div><label class="label">Nome prodotto</label><input class="field" id="edit-offer-name" value="${safe(offer.name)}"/><div class="form-grid"><div><label class="label">Prezzo (€)</label><input class="field" id="edit-offer-price" type="number" min="0" step="0.10" value="${raw}"/></div><div><label class="label">Quantità</label><input class="field" id="edit-offer-qty" type="number" min="0" value="${q}"/></div></div><label class="label">Stato</label><select class="field" id="edit-offer-status">${['Attiva','Bozza','Esaurita'].map(x=>`<option ${offer.status===x?'selected':''}>${x}</option>`).join('')}</select><div class="notice">Modifiche salvate soltanto in questa demo locale.</div><div class="modal-actions"><button class="btn secondary" data-close>Annulla</button><button class="btn" data-save-offer="${safe(id)}">Salva modifiche</button></div>`);
}
document.getElementById('modal-root').addEventListener('click',e=>{const btn=e.target.closest('[data-save-offer]');if(!btn)return;const id=btn.dataset.saveOffer,name=document.getElementById('edit-offer-name')?.value.trim(),price=Number(document.getElementById('edit-offer-price')?.value),qty=Number(document.getElementById('edit-offer-qty')?.value),status=document.getElementById('edit-offer-status')?.value;if(!name||!(price>0)||qty<0||!Number.isFinite(qty)){toast('Controlla nome, prezzo e quantità');return;}const updated={name,price:money(price),rawPrice:price,qty:`${qty} disponibili`,qtyNumber:qty,status};if(id.startsWith('sample-'))state.producerOverrides[id]=updated;else{const i=state.producerOffers.findIndex(o=>o.id===id);if(i>=0)state.producerOffers[i]={...state.producerOffers[i],...updated};}persist();closeModal();renderProducerOffers();toast('Offerta aggiornata nella demo');});
function modalPurchase(){mountModal(`<div class="row between"><h2>Registra un acquisto</h2><button class="close" data-close>×</button></div><label class="label">Prodotto / ingrediente</label><input class="field" id="purchase-name" placeholder="Es. Farina tipo 0"/><div class="form-grid"><div><label class="label">Quantità</label><input class="field" id="purchase-qty" type="number" placeholder="10"/></div><div><label class="label">Costo (€)</label><input class="field" id="purchase-cost" type="number" step="0.10" placeholder="12,00"/></div></div><div class="notice">Registrazione dimostrativa: non aggiorna sistemi gestionali esterni.</div><div class="modal-actions"><button class="btn secondary" data-close>Annulla</button><button class="btn" data-save-purchase>Registra</button></div>`);}
document.getElementById('modal-root').addEventListener('click',e=>{if(e.target.closest('[data-save-purchase]')){const n=document.getElementById('purchase-name').value.trim();if(!n){toast('Inserisci il nome del prodotto');return;}const q=Number(document.getElementById('purchase-qty').value)||1,c=Number(document.getElementById('purchase-cost').value)||0;state.purchases.unshift({name:n,qty:q,cost:c,date:'Oggi'});persist();closeModal();renderProducerStock();toast('Acquisto registrato nella demo');}});
// Keep role navigation labels coherent and the initial view on the customer home.
state.role='consumer';state.tab='Home';state.page='tab';render();

document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-product][role=button]')){e.preventDefault();e.target.click();}});
